select date_trunc('MONTH', o.order_date) as order_month, case when o.discount >= 0.3 then 'high' when o.discount >= 0.09 then 'mid' else 'low' end as discount_bucket, round((100 * sum(case when p.status = 'REFUNDED' then 1 else 0 end)) / count(*), 1) as pct_refunded, round(avg(p.amount), 2) as avg_amount from payments p inner join orders o on p.order_id = o.id group by date_trunc('MONTH', o.order_date), case when o.discount >= 0.3 then 'high' when o.discount >= 0.09 then 'mid' else 'low' end order by 4
